function normalizePhone(raw) {
  const s = String(raw || "").trim();
  if (!s) return "";
  const digits = s.replace(/\D/g, "");
  if (!digits) return "";
  if (digits.startsWith("380") && digits.length === 12) return "+" + digits;
  if (digits.startsWith("0") && digits.length === 10) return "+38" + digits;
  if (digits.length === 9) return "+380" + digits;
  return "+" + digits;
}
const fmt = (n) => (Number(n) || 0).toLocaleString("uk-UA", { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + " ₴";
const fmtNumber = (n) => {
  const s = String(n ?? "").trim();
  if (s !== "" && /^\d+$/.test(s)) return s.padStart(4, "0");
  return s || "—";
};
const todayISO = () => new Date().toISOString().slice(0, 10);
const thisMonthISO = () => new Date().toISOString().slice(0, 7);
const isValidMonthKey = (key) => /^\d{4}-\d{2}$/.test(key || "") && !isNaN(new Date(key + "-01").getTime());
const monthLabel = (key) => {
  const [y, m] = key.split("-");
  return new Date(Number(y), Number(m) - 1, 1).toLocaleDateString("uk-UA", { month: "short", year: "2-digit" });
};

