const worksTotal = (o) => (o.works || []).reduce((s, i) => s + (Number(i.qty) || 0) * (Number(i.price) || 0), 0);
const execTotals = (o) => {
  const list = o.execMaterials || [];
  const purchase = list.reduce((s, i) => s + (Number(i.qty) || 0) * (Number(i.purchasePrice) || 0), 0);
  const client = list.reduce((s, i) => s + (Number(i.qty) || 0) * (Number(i.clientPrice) || 0), 0);
  return { purchase, client, diff: client - purchase };
};
const orderTotal = (o) => worksTotal(o) + execTotals(o).client;

const HISTORY_FIELD_LABELS = {
  dateReceived: "Дата приймання", dateIssued: "Дата видачі", clientName: "Ім'я замовника",
  clientPhone: "Телефон", carModel: "Авто", vin: "VIN", plate: "Номерний знак", comment: "Коментар",
};

function summarizeOrderChanges(oldOrder, newOrder) {
  const changes = [];
  Object.keys(HISTORY_FIELD_LABELS).forEach((key) => {
    const before = (oldOrder[key] || "").toString().trim();
    const after = (newOrder[key] || "").toString().trim();
    if (before !== after) {
      changes.push(`${HISTORY_FIELD_LABELS[key]}: «${before || "—"}» → «${after || "—"}»`);
    }
  });
  const wtBefore = worksTotal(oldOrder), wtAfter = worksTotal(newOrder);
  if (wtBefore !== wtAfter) changes.push(`Сума робіт: ${fmt(wtBefore)} → ${fmt(wtAfter)}`);
  const exBefore = execTotals(oldOrder), exAfter = execTotals(newOrder);
  if (exBefore.client !== exAfter.client) changes.push(`Сума матеріалів: ${fmt(exBefore.client)} → ${fmt(exAfter.client)}`);
  const cwBefore = (oldOrder.works || []).length, cwAfter = (newOrder.works || []).length;
  if (cwBefore !== cwAfter) changes.push(`Позицій робіт: ${cwBefore} → ${cwAfter}`);
  const cmBefore = (oldOrder.execMaterials || []).length, cmAfter = (newOrder.execMaterials || []).length;
  if (cmBefore !== cmAfter) changes.push(`Позицій матеріалів: ${cmBefore} → ${cmAfter}`);
  const ccBefore = (oldOrder.clientMaterials || []).length, ccAfter = (newOrder.clientMaterials || []).length;
  if (ccBefore !== ccAfter) changes.push(`Матеріалів замовника: ${ccBefore} → ${ccAfter}`);
  return changes;
}


function escapeHtml(s) {
  return String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}

