function downloadOrder(order) {
  const html = buildOrderHtml(order);
  const blob = new Blob([html], { type: "text/html;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `naryad-zamovlennya-${fmtNumber(order.number)}.html`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

// Растеризує SVG-логотип у PNG через canvas (jsPDF не вміє SVG напряму)
function svgDataUriToPngDataUri(svgDataUri, scale = 3) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => {
      const w = (img.naturalWidth || 261) * scale;
      const h = (img.naturalHeight || 114) * scale;
      const canvas = document.createElement("canvas");
      canvas.width = w;
      canvas.height = h;
      const ctx = canvas.getContext("2d");
      ctx.drawImage(img, 0, 0, w, h);
      resolve({ dataUri: canvas.toDataURL("image/png"), aspect: w / h });
    };
    img.onerror = reject;
    img.src = svgDataUri;
  });
}

let _logoPngCache = null;
async function getLogoPng() {
  if (!_logoPngCache) _logoPngCache = await svgDataUriToPngDataUri(LOGO_DATA_URI, 3);
  return _logoPngCache;
}

// Формує справжній PDF (A4) для наряд-замовлення і одразу завантажує його
async function downloadOrderPdf(order) {
  const wt = worksTotal(order);
  const ex = execTotals(order);
  const grand = wt + ex.client;

  const doc = new jsPDF({ unit: "mm", format: "a4" });
  const pageWidth = doc.internal.pageSize.getWidth();
  const marginX = 14;
  const rightX = pageWidth - marginX;

  let logoPng = null;
  try { logoPng = await getLogoPng(); } catch (e) { console.error("logo render failed", e); }

  const logoWidth = 38;
  const logoHeight = logoPng ? logoWidth / logoPng.aspect : 17;
  if (logoPng) doc.addImage(logoPng.dataUri, "PNG", marginX, 12, logoWidth, logoHeight);

  doc.setFont("helvetica", "bold");
  doc.setFontSize(15);
  doc.text(`Наряд-замовлення № ${fmtNumber(order.number)}`, rightX, 18, { align: "right" });

  doc.setFont("helvetica", "normal");
  doc.setFontSize(9.5);
  doc.setTextColor(90);
  const datesLine = `Дата приймання: ${order.dateReceived ? new Date(order.dateReceived).toLocaleDateString("uk-UA") : "—"}   ·   Дата видачі: ${order.dateIssued ? new Date(order.dateIssued).toLocaleDateString("uk-UA") : "—"}`;
  doc.text(datesLine, rightX, 24, { align: "right" });

  doc.setDrawColor(26);
  doc.setLineWidth(0.6);
  doc.line(marginX, 40, rightX, 40);

  let y = 48;
  doc.setTextColor(120);
  doc.setFontSize(8);
  doc.text("ЗАМОВНИК", marginX, y);
  doc.text("АВТОМОБІЛЬ", marginX + 90, y);
  y += 5;
  doc.setTextColor(20);
  doc.setFont("helvetica", "bold");
  doc.setFontSize(10.5);
  doc.text(order.clientName || "—", marginX, y);
  doc.text(order.carModel || "—", marginX + 90, y);
  y += 5;
  doc.setFont("helvetica", "normal");
  doc.setFontSize(9.5);
  doc.text(order.clientPhone || "—", marginX, y);
  const carLine2 = [order.plate ? `Держ. номер: ${order.plate}` : "", order.vin ? `VIN: ${order.vin}` : ""].filter(Boolean).join("   ·   ");
  doc.text(carLine2 || "—", marginX + 90, y);
  y += 10;

  doc.setFont("helvetica", "bold");
  doc.setFontSize(10);
  doc.text("РОБОТИ", marginX, y);
  y += 2;

  autoTable(doc, {
    startY: y,
    margin: { left: marginX, right: marginX },
    head: [["Найменування", "К-сть", "Вартість", "Сума"]],
    body: (order.works || []).length
      ? order.works.map((i) => [i.name, String(i.qty), fmt(i.price), fmt(i.qty * i.price)])
      : [["Немає позицій", "", "", ""]],
    styles: { fontSize: 9, cellPadding: 2 },
    headStyles: { fillColor: [26, 26, 26], textColor: 255 },
    columnStyles: { 1: { halign: "right", cellWidth: 20 }, 2: { halign: "right", cellWidth: 30 }, 3: { halign: "right", cellWidth: 30 } },
  });
  y = doc.lastAutoTable.finalY + 6;
  doc.setFont("helvetica", "bold");
  doc.setFontSize(10);
  doc.text(`Разом за роботи:  ${fmt(wt)}`, rightX, y, { align: "right" });
  y += 10;

  doc.text("МАТЕРІАЛИ", marginX, y);
  y += 2;
  autoTable(doc, {
    startY: y,
    margin: { left: marginX, right: marginX },
    head: [["Найменування", "К-сть", "Ціна", "Сума"]],
    body: (order.execMaterials || []).length
      ? order.execMaterials.map((i) => [i.name, String(i.qty), fmt(i.clientPrice), fmt(i.qty * i.clientPrice)])
      : [["Немає позицій", "", "", ""]],
    styles: { fontSize: 9, cellPadding: 2 },
    headStyles: { fillColor: [26, 26, 26], textColor: 255 },
    columnStyles: { 1: { halign: "right", cellWidth: 20 }, 2: { halign: "right", cellWidth: 30 }, 3: { halign: "right", cellWidth: 30 } },
  });
  y = doc.lastAutoTable.finalY + 6;
  doc.setFont("helvetica", "bold");
  doc.setFontSize(10);
  doc.text(`Разом за матеріали:  ${fmt(ex.client)}`, rightX, y, { align: "right" });
  y += 10;

  if ((order.clientMaterials || []).length > 0) {
    doc.text("МАТЕРІАЛИ ЗАМОВНИКА (надані клієнтом)", marginX, y);
    y += 2;
    autoTable(doc, {
      startY: y,
      margin: { left: marginX, right: marginX },
      head: [["Найменування", "К-сть"]],
      body: order.clientMaterials.map((i) => [i.name, String(i.qty)]),
      styles: { fontSize: 9, cellPadding: 2 },
      headStyles: { fillColor: [26, 26, 26], textColor: 255 },
      columnStyles: { 1: { halign: "right", cellWidth: 20 } },
    });
    y = doc.lastAutoTable.finalY + 8;
  }

  if (y > 250) { doc.addPage(); y = 24; }

  doc.setFillColor(244, 249, 247);
  doc.setDrawColor(26);
  doc.setLineWidth(0.5);
  doc.rect(marginX, y, rightX - marginX, 14, "FD");
  doc.setFont("helvetica", "bold");
  doc.setFontSize(8.5);
  doc.setTextColor(26);
  doc.text("ЗАГАЛЬНА СУМА ДО СПЛАТИ", marginX + 4, y + 9);
  doc.setFontSize(11);
  doc.text(fmt(grand), rightX - 4, y + 9, { align: "right" });
  y += 30;

  if (y > 270) { doc.addPage(); y = 40; }
  const colWidth = (rightX - marginX - 10) / 2;
  doc.setDrawColor(26);
  doc.setLineWidth(0.3);
  doc.line(marginX, y, marginX + colWidth, y);
  doc.line(marginX + colWidth + 10, y, rightX, y);
  doc.setFont("helvetica", "normal");
  doc.setFontSize(9);
  doc.setTextColor(60);
  doc.text("Підпис замовника", marginX, y + 5);
  doc.text("Підпис виконавця", marginX + colWidth + 10, y + 5);

  doc.save(`naryad-zamovlennya-${fmtNumber(order.number)}.pdf`);
}



