function deriveClients(orders) {
  const groups = {};
  const sorted = [...orders].sort((a, b) => new Date(a.dateReceived) - new Date(b.dateReceived));
  sorted.forEach((o) => {
    const key = (o.clientPhone || "").trim() || `ім'я:${(o.clientName || "без імені").trim().toLowerCase()}`;
    if (!groups[key]) groups[key] = [];
    groups[key].push(o);
  });
  return Object.entries(groups)
    .map(([key, list], idx) => {
      const lastOrder = [...list].sort((a, b) => new Date(b.dateReceived) - new Date(a.dateReceived))[0];
      const lastVisit = lastOrder.dateIssued || lastOrder.dateReceived;
      const totalSum = list.reduce((s, o) => s + orderTotal(o), 0);
      const carMap = {};
      list.forEach((o) => {
        const carKey = [o.carModel || "", o.plate || ""].join("|").toLowerCase();
        if (!carMap[carKey] && (o.carModel || o.plate)) {
          carMap[carKey] = { model: o.carModel || "—", plate: o.plate || "", vin: o.vin || "" };
        }
      });
      const cars = Object.values(carMap);
      return {
        id: "К-" + String(idx + 1).padStart(3, "0"),
        key,
        name: lastOrder.clientName || "Без імені",
        phone: lastOrder.clientPhone || "—",
        car: [lastOrder.carModel, lastOrder.plate].filter(Boolean).join(" · "),
        cars,
        vin: lastOrder.vin || "",
        status: list.length >= 2 ? "Постійний" : "Новий",
        lastVisit,
        visits: list.length,
        totalSum,
        orders: list.sort((a, b) => new Date(b.dateReceived) - new Date(a.dateReceived)),
      };
    })
    .sort((a, b) => new Date(b.lastVisit) - new Date(a.lastVisit));
}

function sanitizeClientKey(key) {
  return "note_" + String(key).replace(/[^a-zA-Zа-яА-ЯіІїЇєЄ0-9]/g, "_").slice(0, 120);
}

