function Field({ label, children }) {
  return <div><span style={labelStyle}>{label}</span>{children}</div>;
}
function Row2({ children }) {
  return <div style={{ display: "flex", gap: 8 }}>{children}</div>;
}
function PrimaryButton({ children, onClick, disabled, style }) {
  return (
    <button onClick={onClick} disabled={disabled} style={{
      background: disabled ? COLORS.border : COLORS.accent, color: disabled ? COLORS.textMuted : "#ffffff",
      fontFamily: "'Inter', sans-serif", fontWeight: 700, fontSize: 14.5,
      border: "none", borderRadius: 12, padding: "13px 16px", cursor: disabled ? "default" : "pointer",
      width: "100%", ...style,
    }}>{children}</button>
  );
}
function ConfirmDialog({ title, message, confirmLabel, danger, onConfirm, onCancel }) {
  return (
    <div style={{ position: "absolute", inset: 0, background: "rgba(36,51,48,0.45)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 60, padding: 24 }} onClick={onCancel}>
      <div onClick={(e) => e.stopPropagation()} style={{ background: COLORS.surface, borderRadius: 16, padding: 20, width: "100%", maxWidth: 320, display: "flex", flexDirection: "column", gap: 14, border: `1px solid ${COLORS.border}` }}>
        <div style={{ fontFamily: "'Oswald', sans-serif", fontSize: 17, color: COLORS.text }}>{title}</div>
        <div style={{ fontSize: 13.5, color: COLORS.textMuted, lineHeight: 1.5 }}>{message}</div>
        <div style={{ display: "flex", gap: 8 }}>
          <button onClick={onCancel} style={{ ...inputStyle, flex: 1, background: COLORS.surface2, cursor: "pointer", textAlign: "center", fontWeight: 600, color: COLORS.text }}>Скасувати</button>
          <button onClick={onConfirm} style={{ ...inputStyle, flex: 1, background: danger ? COLORS.danger : COLORS.accent, border: "none", cursor: "pointer", textAlign: "center", fontWeight: 700, color: "#fff" }}>{confirmLabel || "Так"}</button>
        </div>
      </div>
    </div>
  );
}

function ToastBanner({ message, danger }) {
  if (!message) return null;
  return (
    <div style={{
      position: "absolute", top: 12, left: 12, right: 12, zIndex: 70,
      background: danger ? COLORS.danger : COLORS.text, color: "#fff", fontSize: 12.5, fontWeight: 600,
      padding: "10px 14px", borderRadius: 10, textAlign: "center", boxShadow: "0 6px 18px rgba(0,0,0,0.18)",
    }}>{message}</div>
  );
}

function Sheet({ title, onClose, children, wide }) {
  return (
    <div style={{ position: "absolute", inset: 0, background: "rgba(36,51,48,0.35)", display: "flex", alignItems: "flex-end", zIndex: 50 }} onClick={onClose}>
      <div onClick={(e) => e.stopPropagation()} style={{
        background: COLORS.surface, width: "100%", maxHeight: "90%", borderRadius: "20px 20px 0 0",
        padding: "18px 18px 24px", overflowY: "auto", borderTop: `1px solid ${COLORS.border}`,
        display: "flex", flexDirection: "column", gap: 13,
      }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <h2 style={{ fontFamily: "'Oswald', sans-serif", fontWeight: 600, fontSize: 18, letterSpacing: 0.3, margin: 0, color: COLORS.text }}>{title}</h2>
          <button onClick={onClose} style={iconBtnStyle}><X size={18} color={COLORS.textMuted} /></button>
        </div>
        {children}
      </div>
    </div>
  );
}
function EmptyState({ icon: Icon, title, hint }) {
  return (
    <div style={{ textAlign: "center", padding: "50px 20px", color: COLORS.textMuted }}>
      <Icon size={30} style={{ opacity: 0.4, marginBottom: 10 }} />
      <div style={{ fontFamily: "'Oswald', sans-serif", fontSize: 16, color: COLORS.text, marginBottom: 4 }}>{title}</div>
      <div style={{ fontSize: 13 }}>{hint}</div>
    </div>
  );
}
function SectionLabel({ children, right }) {
  return (
    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: 4 }}>
      <div style={{ fontSize: 11, fontWeight: 700, letterSpacing: 0.6, color: COLORS.textMuted, textTransform: "uppercase" }}>{children}</div>
      {right}
    </div>
  );
}

const UA_MONTHS = ["Січень", "Лютий", "Березень", "Квітень", "Травень", "Червень", "Липень", "Серпень", "Вересень", "Жовтень", "Листопад", "Грудень"];

function MonthPicker({ value, onChange }) {
  const [open, setOpen] = useState(false);
  const [y, m] = value.split("-").map(Number);
  const label = new Date(y, m - 1, 1).toLocaleDateString("uk-UA", { month: "long", year: "numeric" });

  const shift = (delta) => {
    let ny = y, nm = m + delta;
    if (nm < 1) { nm = 12; ny -= 1; }
    if (nm > 12) { nm = 1; ny += 1; }
    onChange(`${ny}-${String(nm).padStart(2, "0")}`);
  };

  const nowYear = new Date().getFullYear();
  const years = [];
  for (let yy = nowYear - 4; yy <= nowYear + 1; yy++) years.push(yy);

  return (
    <div>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", background: COLORS.surface2, border: `1px solid ${COLORS.border}`, borderRadius: 12, padding: "6px 6px" }}>
        <button onClick={() => shift(-1)} style={iconBtnStyle}><ChevronLeft size={17} color={COLORS.text} /></button>
        <button onClick={() => setOpen(true)} style={{ background: "none", border: "none", cursor: "pointer", display: "flex", alignItems: "center", gap: 6, padding: "4px 8px" }}>
          <Calendar size={14} color={COLORS.accent} />
          <span style={{ fontFamily: "'Oswald', sans-serif", fontSize: 15, color: COLORS.text, textTransform: "capitalize" }}>{label}</span>
        </button>
        <button onClick={() => shift(1)} style={iconBtnStyle}><ChevronRight size={17} color={COLORS.text} /></button>
      </div>

      {open && (
        <Sheet title="Обрати місяць" onClose={() => setOpen(false)}>
          <Field label="Місяць">
            <select style={inputStyle} value={m} onChange={(e) => onChange(`${y}-${String(Number(e.target.value)).padStart(2, "0")}`)}>
              {UA_MONTHS.map((name, i) => <option key={i} value={i + 1}>{name}</option>)}
            </select>
          </Field>
          <Field label="Рік">
            <select style={inputStyle} value={y} onChange={(e) => onChange(`${Number(e.target.value)}-${String(m).padStart(2, "0")}`)}>
              {years.map((yy) => <option key={yy} value={yy}>{yy}</option>)}
            </select>
          </Field>
          <PrimaryButton onClick={() => { onChange(thisMonthISO()); setOpen(false); }} style={{ background: COLORS.surface2, color: COLORS.text, border: `1px solid ${COLORS.border}` }}>Поточний місяць</PrimaryButton>
          <PrimaryButton onClick={() => setOpen(false)}>Готово</PrimaryButton>
        </Sheet>
      )}
    </div>
  );
}
function TotalLine({ label, value, big, color }) {
  return (
    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: big ? "8px 2px" : "3px 2px" }}>
      <span style={{ color: COLORS.textMuted, fontSize: big ? 13.5 : 12.5 }}>{label}</span>
      <span style={{ fontFamily: "'IBM Plex Mono', monospace", fontWeight: big ? 700 : 600, fontSize: big ? 19 : 13.5, color: color || COLORS.text }}>{fmt(value)}</span>
    </div>
  );
}

