function OrderHistoryLog({ history }) {
  const [open, setOpen] = useState(false);
  const sorted = [...history].sort((a, b) => b.at - a.at);
  return (
    <div>
      <button onClick={() => setOpen((v) => !v)} style={{ background: "none", border: "none", padding: 0, cursor: "pointer", display: "flex", alignItems: "center", gap: 5, color: COLORS.textMuted, fontSize: 11.5, fontWeight: 700, textTransform: "uppercase", letterSpacing: 0.5 }}>
        <History size={12} /> Історія змін ({history.length}) {open ? "▲" : "▼"}
      </button>
      {open && (
        <div style={{ display: "flex", flexDirection: "column", gap: 8, marginTop: 8 }}>
          {sorted.map((h, i) => (
            <div key={i} style={{ background: COLORS.surface2, borderRadius: 8, padding: "8px 10px" }}>
              <div style={{ fontSize: 11, color: COLORS.textMuted, marginBottom: 4, fontFamily: "'IBM Plex Mono', monospace" }}>
                {new Date(h.at).toLocaleString("uk-UA", { day: "2-digit", month: "2-digit", year: "numeric", hour: "2-digit", minute: "2-digit" })}
              </div>
              {h.changes.map((c, j) => (
                <div key={j} style={{ fontSize: 12, color: COLORS.text, lineHeight: 1.5 }}>{c}</div>
              ))}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

