const ORDER_SORT_OPTIONS = [
  { key: "date_desc", label: "Дата: спочатку нові" },
  { key: "date_asc", label: "Дата: спочатку старі" },
  { key: "sum_desc", label: "Сума: спочатку більша" },
  { key: "sum_asc", label: "Сума: спочатку менша" },
  { key: "number_desc", label: "Номер: спадання" },
  { key: "number_asc", label: "Номер: зростання" },
  { key: "client_az", label: "Клієнт: А—Я" },
];

function sortOrders(list, sortBy) {
  const arr = [...list];
  switch (sortBy) {
    case "date_asc": return arr.sort((a, b) => new Date(a.dateReceived) - new Date(b.dateReceived));
    case "sum_desc": return arr.sort((a, b) => orderTotal(b) - orderTotal(a));
    case "sum_asc": return arr.sort((a, b) => orderTotal(a) - orderTotal(b));
    case "number_desc": return arr.sort((a, b) => (Number(b.number) || 0) - (Number(a.number) || 0));
    case "number_asc": return arr.sort((a, b) => (Number(a.number) || 0) - (Number(b.number) || 0));
    case "client_az": return arr.sort((a, b) => (a.clientName || "").localeCompare(b.clientName || "", "uk"));
    case "date_desc":
    default: return arr.sort((a, b) => new Date(b.dateReceived) - new Date(a.dateReceived));
  }
}

function OrdersTab({ orders, onNew, onOpen }) {
  const [query, setQuery] = useState("");
  const [sortBy, setSortBy] = useState("date_desc");
  const filtered = useMemo(() => {
    const q = query.toLowerCase();
    const list = orders.filter((o) => !q || (o.clientName + o.clientPhone + o.carModel + o.plate + o.vin).toLowerCase().includes(q));
    return sortOrders(list, sortBy);
  }, [orders, query, sortBy]);

  return (
    <div style={{ display: "flex", flexDirection: "column", height: "100%" }}>
      <div style={{ padding: "14px 16px 8px" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
          <h1 style={{ fontFamily: "'Oswald', sans-serif", fontSize: 23, color: COLORS.text, margin: 0 }}>Наряд-замовлення</h1>
          <button onClick={onNew} style={{ ...iconBtnStyle, width: 34, height: 34, background: COLORS.accent, border: "none" }}><Plus size={18} color="#ffffff" /></button>
        </div>
        <div style={{ position: "relative", marginBottom: 8 }}>
          <Search size={14} color={COLORS.textMuted} style={{ position: "absolute", left: 12, top: 12 }} />
          <input style={{ ...inputStyle, paddingLeft: 32 }} placeholder="Пошук: клієнт, авто, VIN, номер..." value={query} onChange={(e) => setQuery(e.target.value)} />
        </div>
        <div style={{ position: "relative" }}>
          <ArrowUpDown size={13} color={COLORS.textMuted} style={{ position: "absolute", left: 12, top: 12 }} />
          <select style={{ ...inputStyle, paddingLeft: 32 }} value={sortBy} onChange={(e) => setSortBy(e.target.value)}>
            {ORDER_SORT_OPTIONS.map((o) => <option key={o.key} value={o.key}>{o.label}</option>)}
          </select>
        </div>
      </div>
      <div style={{ flex: 1, overflowY: "auto", padding: "8px 16px 90px", display: "flex", flexDirection: "column", gap: 10 }}>
        {filtered.length === 0 && <EmptyState icon={Wrench} title="Пока пусто" hint="Натисніть «+», щоб створити перше наряд-замовлення" />}
        {filtered.map((o) => <OrderCard key={o.id} order={o} onOpen={() => onOpen(o)} />)}
      </div>
    </div>
  );
}

