const CLIENT_SORT_OPTIONS = [
  { key: "recent", label: "Останній візит: спочатку недавні" },
  { key: "visits_desc", label: "Кількість візитів: більше" },
  { key: "sum_desc", label: "Сума: спочатку більша" },
  { key: "sum_asc", label: "Сума: спочатку менша" },
  { key: "name_az", label: "Ім'я: А—Я" },
];

function sortClients(list, sortBy) {
  const arr = [...list];
  switch (sortBy) {
    case "visits_desc": return arr.sort((a, b) => b.visits - a.visits);
    case "sum_desc": return arr.sort((a, b) => b.totalSum - a.totalSum);
    case "sum_asc": return arr.sort((a, b) => a.totalSum - b.totalSum);
    case "name_az": return arr.sort((a, b) => a.name.localeCompare(b.name, "uk"));
    case "recent":
    default: return arr.sort((a, b) => new Date(b.lastVisit) - new Date(a.lastVisit));
  }
}

function ClientsTab({ orders, onOpenOrder, clientNotes, onSaveNote, upsertOrder }) {
  const [query, setQuery] = useState("");
  const [detail, setDetail] = useState(null);
  const [sortBy, setSortBy] = useState("recent");
  const [noteDraft, setNoteDraft] = useState("");
  const [renaming, setRenaming] = useState(null);
  const [merging, setMerging] = useState(null);
  const [saveError, setSaveError] = useState("");
  const [carFilter, setCarFilter] = useState("all");
  const clients = useMemo(() => deriveClients(orders), [orders]);

  useEffect(() => {
    setNoteDraft(detail ? (clientNotes[sanitizeClientKey(detail.key)] || "") : "");
    setCarFilter("all");
  }, [detail]);

  const carKeyOf = (o) => [o.carModel || "", o.plate || ""].join("|").toLowerCase();
  const historyOrders = detail ? (carFilter === "all" ? detail.orders : detail.orders.filter((o) => carKeyOf(o) === carFilter)) : [];

  const handleRename = async (client, newName, newPhone) => {
    const normPhone = normalizePhone(newPhone);
    const oldKey = sanitizeClientKey(client.key);
    const newKeyRaw = normPhone || `ім'я:${newName.trim().toLowerCase()}`;
    const newKey = sanitizeClientKey(newKeyRaw);
    try {
      for (const o of client.orders) {
        const ok = await upsertOrder({ ...o, clientName: newName.trim(), clientPhone: normPhone });
        if (ok === false) throw new Error("save failed");
      }
      if (oldKey !== newKey && clientNotes[oldKey]) {
        await onSaveNote(newKey, clientNotes[oldKey]);
        await onSaveNote(oldKey, "");
      }
      setRenaming(null);
      setDetail(null);
      setSaveError("");
    } catch (e) {
      setSaveError("Не вдалося зберегти зміни. Перевірте інтернет-з'єднання і спробуйте ще раз.");
    }
  };

  const [mergeCandidate, setMergeCandidate] = useState(null);
  const handleMerge = async (source, target) => {
    try {
      for (const o of source.orders) {
        const ok = await upsertOrder({ ...o, clientName: target.name, clientPhone: target.phone === "—" ? "" : target.phone });
        if (ok === false) throw new Error("save failed");
      }
      const oldKey = sanitizeClientKey(source.key);
      const newKey = sanitizeClientKey(target.key);
      const mergedNote = [clientNotes[newKey], clientNotes[oldKey]].filter(Boolean).join("\n---\n");
      if (mergedNote) await onSaveNote(newKey, mergedNote);
      if (clientNotes[oldKey]) await onSaveNote(oldKey, "");
      setMerging(null);
      setDetail(null);
      setSaveError("");
    } catch (e) {
      setSaveError("Не вдалося об'єднати клієнтів. Перевірте інтернет-з'єднання і спробуйте ще раз.");
    }
  };
  const filtered = useMemo(() => {
    const list = clients.filter((c) => (c.name + c.phone + c.car).toLowerCase().includes(query.toLowerCase()));
    return sortClients(list, sortBy);
  }, [clients, query, sortBy]);

  return (
    <div style={{ display: "flex", flexDirection: "column", height: "100%" }}>
      <div style={{ padding: "14px 16px 8px" }}>
        <h1 style={{ fontFamily: "'Oswald', sans-serif", fontSize: 23, color: COLORS.text, margin: "0 0 10px" }}>База клієнтів</h1>
        <div style={{ position: "relative", marginBottom: 8 }}>
          <Search size={14} color={COLORS.textMuted} style={{ position: "absolute", left: 12, top: 12 }} />
          <input style={{ ...inputStyle, paddingLeft: 32 }} placeholder="Пошук клієнта..." value={query} onChange={(e) => setQuery(e.target.value)} />
        </div>
        <div style={{ position: "relative" }}>
          <ArrowUpDown size={13} color={COLORS.textMuted} style={{ position: "absolute", left: 12, top: 12 }} />
          <select style={{ ...inputStyle, paddingLeft: 32 }} value={sortBy} onChange={(e) => setSortBy(e.target.value)}>
            {CLIENT_SORT_OPTIONS.map((o) => <option key={o.key} value={o.key}>{o.label}</option>)}
          </select>
        </div>
      </div>

      <div style={{ flex: 1, overflowY: "auto", padding: "4px 16px 90px", display: "flex", flexDirection: "column", gap: 8 }}>
        {filtered.length === 0 && <EmptyState icon={Users} title="Клієнтів ще немає" hint="Клієнти з'являться автоматично після створення наряд-замовлень" />}
        {filtered.map((c) => (
          <div key={c.id} onClick={() => setDetail(c)} style={{ background: COLORS.surface, border: `1px solid ${COLORS.border}`, borderRadius: 14, padding: "12px 14px", cursor: "pointer" }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
              <div>
                <div style={{ fontFamily: "'Oswald', sans-serif", fontSize: 15, color: COLORS.text, display: "flex", alignItems: "center", gap: 6 }}>
                  {c.name}
                  {c.status === "Постійний" && <Star size={12} color={COLORS.warn} fill={COLORS.warn} />}
                </div>
                <div style={{ fontSize: 11.5, color: COLORS.textMuted, marginTop: 2 }}>{c.id} · {c.phone}</div>
              </div>
              <span style={{
                fontSize: 10.5, padding: "3px 8px", borderRadius: 20, textTransform: "uppercase",
                color: c.status === "Постійний" ? COLORS.warn : COLORS.accent2,
                background: (c.status === "Постійний" ? COLORS.warn : COLORS.accent2) + "22",
                border: `1px solid ${(c.status === "Постійний" ? COLORS.warn : COLORS.accent2)}55`,
              }}>{c.status}</span>
            </div>
            <div style={{ display: "flex", justifyContent: "space-between", marginTop: 9, fontSize: 12 }}>
              <span style={{ color: COLORS.textMuted }}>{c.visits} візит{c.visits === 1 ? "" : c.visits < 5 ? "и" : "ів"} · останній {new Date(c.lastVisit).toLocaleDateString("uk-UA")}</span>
              <span style={{ fontFamily: "'IBM Plex Mono', monospace", color: COLORS.accent, fontWeight: 700 }}>{fmt(c.totalSum)}</span>
            </div>
          </div>
        ))}
      </div>

      {detail && (
        <Sheet title={detail.name} onClose={() => setDetail(null)}>
          <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
            <Chip label="ID" value={detail.id} />
            <Chip label="Статус" value={detail.status} color={detail.status === "Постійний" ? COLORS.warn : COLORS.accent2} />
          </div>
          <div style={{ fontSize: 13.5, color: COLORS.text, display: "flex", alignItems: "center", gap: 5 }}><Phone size={13} color={COLORS.textMuted} />{detail.phone}</div>
          {(detail.cars || []).length > 0 && (
            <div>
              <SectionLabel>{detail.cars.length > 1 ? `Автомобілі (${detail.cars.length})` : "Автомобіль"}</SectionLabel>
              <div style={{ display: "flex", flexDirection: "column", gap: 4, marginTop: 6 }}>
                {detail.cars.map((c, i) => (
                  <div key={i} style={{ fontSize: 13.5, color: COLORS.text, display: "flex", alignItems: "center", gap: 5 }}>
                    <Car size={13} color={COLORS.textMuted} />
                    {c.model}{c.plate ? ` · ${c.plate}` : ""}{c.vin ? ` · VIN: ${c.vin}` : ""}
                  </div>
                ))}
              </div>
            </div>
          )}
          <div style={{ display: "flex", gap: 8 }}>
            <StatBox label="Візитів" value={detail.visits} />
            <StatBox label="Останній візит" value={new Date(detail.lastVisit).toLocaleDateString("uk-UA")} />
          </div>
          <StatBox label="Загальна сума за всі візити" value={fmt(detail.totalSum)} wide accent />

          <div>
            <SectionLabel>Коментар до клієнта</SectionLabel>
            <textarea style={{ ...inputStyle, minHeight: 60, marginTop: 6 }} value={noteDraft} onChange={(e) => setNoteDraft(e.target.value)} placeholder="Наприклад: любить каву перед прийомом, завжди платить карткою..." />
            <button onClick={() => onSaveNote(sanitizeClientKey(detail.key), noteDraft)} style={{ ...inputStyle, marginTop: 6, background: COLORS.accent2 + "18", border: `1px solid ${COLORS.accent2}55`, cursor: "pointer", textAlign: "center", fontWeight: 600, color: COLORS.accent2 }}>Зберегти коментар</button>
          </div>

          <div>
            <SectionLabel>Історія замовлень</SectionLabel>
            {(detail.cars || []).length > 1 && (
              <div style={{ display: "flex", gap: 6, overflowX: "auto", marginTop: 6, paddingBottom: 2 }}>
                <button onClick={() => setCarFilter("all")} style={{
                  flexShrink: 0, fontSize: 11.5, fontWeight: 600, padding: "5px 10px", borderRadius: 20, cursor: "pointer",
                  background: carFilter === "all" ? COLORS.accent + "22" : "transparent",
                  border: `1px solid ${carFilter === "all" ? COLORS.accent + "88" : COLORS.border}`,
                  color: carFilter === "all" ? COLORS.accent : COLORS.textMuted,
                }}>Усі авто</button>
                {detail.cars.map((c) => {
                  const key = [c.model || "", c.plate || ""].join("|").toLowerCase();
                  return (
                    <button key={key} onClick={() => setCarFilter(key)} style={{
                      flexShrink: 0, fontSize: 11.5, fontWeight: 600, padding: "5px 10px", borderRadius: 20, cursor: "pointer",
                      background: carFilter === key ? COLORS.accent + "22" : "transparent",
                      border: `1px solid ${carFilter === key ? COLORS.accent + "88" : COLORS.border}`,
                      color: carFilter === key ? COLORS.accent : COLORS.textMuted,
                    }}>{c.model}{c.plate ? ` · ${c.plate}` : ""}</button>
                  );
                })}
              </div>
            )}
            <div style={{ display: "flex", flexDirection: "column", gap: 6, marginTop: 6 }}>
              {historyOrders.length === 0 && <div style={{ fontSize: 12.5, color: COLORS.textMuted }}>Немає замовлень для цього авто</div>}
              {historyOrders.map((o) => (
                <div key={o.id} onClick={() => onOpenOrder(o)} style={{ display: "flex", justifyContent: "space-between", background: COLORS.surface2, borderRadius: 8, padding: "9px 11px", cursor: "pointer" }}>
                  <span style={{ fontSize: 12.5, color: COLORS.text }}>№{fmtNumber(o.number)} · {new Date(o.dateReceived).toLocaleDateString("uk-UA")}</span>
                  <span style={{ fontFamily: "'IBM Plex Mono', monospace", fontSize: 12.5, color: COLORS.accent }}>{fmt(orderTotal(o))}</span>
                </div>
              ))}
            </div>
          </div>

          {saveError && <div style={{ fontSize: 12, color: COLORS.danger, background: COLORS.danger + "12", border: `1px solid ${COLORS.danger}44`, borderRadius: 8, padding: "8px 10px" }}>{saveError}</div>}

          <div style={{ display: "flex", gap: 8 }}>
            <button onClick={() => setRenaming({ name: detail.name, phone: detail.phone === "—" ? "" : detail.phone })} style={{ ...inputStyle, background: COLORS.surface2, cursor: "pointer", textAlign: "center", fontWeight: 600, color: COLORS.text }}>Перейменувати</button>
            <button onClick={() => setMerging({ query: "" })} style={{ ...inputStyle, background: COLORS.surface2, cursor: "pointer", textAlign: "center", fontWeight: 600, color: COLORS.text }}>Об'єднати з іншим</button>
          </div>
        </Sheet>
      )}

      {renaming && (
        <Sheet title="Перейменувати клієнта" onClose={() => setRenaming(null)}>
          <div style={{ fontSize: 12.5, color: COLORS.textMuted }}>Зміна імені чи телефону оновить усі {detail.visits} наряд-замовлення цього клієнта одразу.</div>
          <Field label="Ім'я"><input style={inputStyle} value={renaming.name} onChange={(e) => setRenaming({ ...renaming, name: e.target.value })} /></Field>
          <Field label="Телефон"><input style={inputStyle} value={renaming.phone} onChange={(e) => setRenaming({ ...renaming, phone: e.target.value })} placeholder="+380..." /></Field>
          <PrimaryButton disabled={!renaming.name.trim()} onClick={() => handleRename(detail, renaming.name, renaming.phone)}>Зберегти для всіх замовлень</PrimaryButton>
        </Sheet>
      )}

      {merging && (
        <Sheet title="Об'єднати з іншим клієнтом" onClose={() => setMerging(null)}>
          <div style={{ fontSize: 12.5, color: COLORS.textMuted }}>Оберіть клієнта, з яким об'єднати «{detail.name}». Усі його замовлення перепишуться на обраного клієнта.</div>
          <div style={{ position: "relative" }}>
            <Search size={14} color={COLORS.textMuted} style={{ position: "absolute", left: 12, top: 12 }} />
            <input style={{ ...inputStyle, paddingLeft: 32 }} placeholder="Пошук клієнта..." value={merging.query} onChange={(e) => setMerging({ ...merging, query: e.target.value })} />
          </div>
          <div style={{ display: "flex", flexDirection: "column", gap: 6, maxHeight: 320, overflowY: "auto" }}>
            {clients.filter((c) => c.key !== detail.key && (c.name + c.phone).toLowerCase().includes(merging.query.toLowerCase())).map((c) => (
              <div key={c.id} onClick={() => setMergeCandidate(c)} style={{ background: COLORS.surface2, borderRadius: 8, padding: "10px 12px", cursor: "pointer", display: "flex", justifyContent: "space-between" }}>
                <span style={{ fontSize: 13, color: COLORS.text }}>{c.name}</span>
                <span style={{ fontSize: 12, color: COLORS.textMuted }}>{c.phone} · {c.visits} візит.</span>
              </div>
            ))}
          </div>
        </Sheet>
      )}

      {mergeCandidate && detail && (
        <ConfirmDialog
          title="Об'єднати клієнтів?"
          message={`Усі ${detail.visits} замовлення «${detail.name}» будуть переписані на «${mergeCandidate.name}» (${mergeCandidate.phone}). Дію не можна скасувати.`}
          confirmLabel="Об'єднати"
          danger
          onCancel={() => setMergeCandidate(null)}
          onConfirm={() => { handleMerge(detail, mergeCandidate); setMergeCandidate(null); }}
        />
      )}
    </div>
  );
}

