/* ------------------------------------------------------------------ */

function csvEscape(v) {
  const s = String(v ?? "");
  if (/[",\n;]/.test(s)) return '"' + s.replace(/"/g, '""') + '"';
  return s;
}

function downloadTextFile(filename, content, mime) {
  const blob = new Blob([content], { type: mime });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

function exportOrdersCsv(orders) {
  const head = ["Номер", "Дата приймання", "Дата видачі", "Клієнт", "Телефон", "Авто", "VIN", "Номерний знак", "Сума робіт", "Сума матеріалів (замовнику)", "Різниця матеріалів", "Загальна сума", "Коментар"];
  const rows = [...orders].sort((a, b) => (Number(a.number) || 0) - (Number(b.number) || 0)).map((o) => {
    const ex = execTotals(o);
    return [
      fmtNumber(o.number), o.dateReceived || "", o.dateIssued || "", o.clientName || "", o.clientPhone || "",
      o.carModel || "", o.vin || "", o.plate || "", worksTotal(o).toFixed(2), ex.client.toFixed(2), ex.diff.toFixed(2), orderTotal(o).toFixed(2), o.comment || "",
    ];
  });
  const csv = [head, ...rows].map((r) => r.map(csvEscape).join(";")).join("\r\n");
  downloadTextFile("naryady-" + todayISO() + ".csv", "﻿" + csv, "text/csv;charset=utf-8");
}

function exportClientsCsv(clients) {
  const head = ["ID", "Ім'я", "Телефон", "Автомобілі", "Статус", "Останній візит", "Візитів", "Загальна сума"];
  const rows = clients.map((c) => [
    c.id, c.name, c.phone === "—" ? "" : c.phone,
    (c.cars || []).map((x) => [x.model, x.plate].filter(Boolean).join(" ")).join(" | "),
    c.status, c.lastVisit || "", c.visits, c.totalSum.toFixed(2),
  ]);
  const csv = [head, ...rows].map((r) => r.map(csvEscape).join(";")).join("\r\n");
  downloadTextFile("kliyenty-" + todayISO() + ".csv", "﻿" + csv, "text/csv;charset=utf-8");
}

function exportFullBackupJson(data) {
  downloadTextFile("sto-backup-" + todayISO() + ".json", JSON.stringify(data, null, 2), "application/json;charset=utf-8");
}

function StatsTab({ orders, expenses, split, setSplit, clientNotes }) {
  const [month, setMonth] = useState(thisMonthISO());
  const [editingSplit, setEditingSplit] = useState(false);
  const [exporting, setExporting] = useState(false);
  const safeMonth = isValidMonthKey(month) ? month : thisMonthISO();
  const allClients = useMemo(() => deriveClients(orders), [orders]);

  const ordersInMonth = orders.filter((o) => (o.dateReceived || "").slice(0, 7) === safeMonth);
  const worksSum = ordersInMonth.reduce((s, o) => s + worksTotal(o), 0);
  const partsSum = ordersInMonth.reduce((s, o) => s + execTotals(o).diff, 0);
  const mechanicAmt = worksSum * (Number(split.mechanic) || 0) / 100;
  const partnerAAmt = worksSum * (Number(split.partnerA) || 0) / 100;
  const partnerBAmt = worksSum * (Number(split.partnerB) || 0) / 100;
  const visits = ordersInMonth.length;
  const avgCheck = visits ? ordersInMonth.reduce((s, o) => s + orderTotal(o), 0) / visits : 0;
  const expensesSum = expenses.filter((e) => (e.date || "").slice(0, 7) === safeMonth).reduce((s, e) => s + Number(e.amount), 0);
  const profit = worksSum + partsSum - expensesSum - mechanicAmt;
  const pctSum = (Number(split.mechanic) || 0) + (Number(split.partnerA) || 0) + (Number(split.partnerB) || 0);

  const chartData = useMemo(() => {
    const map = {};
    const now = new Date(safeMonth + "-01");
    for (let i = 5; i >= 0; i--) {
      const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
      const key = d.toISOString().slice(0, 7);
      map[key] = { key, label: monthLabel(key), Дохід: 0, Витрати: 0 };
    }
    orders.forEach((o) => {
      const key = (o.dateReceived || "").slice(0, 7);
      if (map[key]) map[key].Дохід += worksTotal(o) + execTotals(o).diff;
    });
    expenses.forEach((e) => {
      const key = (e.date || "").slice(0, 7);
      if (map[key]) map[key].Витрати += Number(e.amount);
    });
    return Object.values(map);
  }, [orders, expenses, safeMonth]);

  return (
    <div style={{ height: "100%", overflowY: "auto", padding: "14px 16px 90px" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
        <h1 style={{ fontFamily: "'Oswald', sans-serif", fontSize: 23, color: COLORS.text, margin: 0 }}>Статистика</h1>
        <button onClick={() => setEditingSplit(true)} style={iconBtnStyle}><Settings2 size={16} color={COLORS.textMuted} /></button>
      </div>
      <Field label="Період (місяць)"><MonthPicker value={safeMonth} onChange={setMonth} /></Field>

      <SectionLabel>Резервна копія та експорт</SectionLabel>
      <div style={{ display: "flex", flexDirection: "column", gap: 6, marginTop: 6 }}>
        <button onClick={() => exportOrdersCsv(orders)} style={{ ...inputStyle, background: COLORS.surface2, cursor: "pointer", textAlign: "center", fontWeight: 600, color: COLORS.text, display: "flex", alignItems: "center", justifyContent: "center", gap: 7 }}>
          <Download size={14} /> Експорт наряд-замовлень (CSV)
        </button>
        <button onClick={() => exportClientsCsv(allClients)} style={{ ...inputStyle, background: COLORS.surface2, cursor: "pointer", textAlign: "center", fontWeight: 600, color: COLORS.text, display: "flex", alignItems: "center", justifyContent: "center", gap: 7 }}>
          <Download size={14} /> Експорт клієнтів (CSV)
        </button>
        <button onClick={() => exportFullBackupJson({ exportedAt: new Date().toISOString(), orders, expenses, split, clientNotes })} style={{ ...inputStyle, background: COLORS.accent + "18", border: `1px solid ${COLORS.accent}55`, cursor: "pointer", textAlign: "center", fontWeight: 600, color: COLORS.accent, display: "flex", alignItems: "center", justifyContent: "center", gap: 7 }}>
          <Download size={14} /> Повна резервна копія (JSON)
        </button>
      </div>

      <div style={{ marginTop: 16, display: "flex", flexDirection: "column", gap: 8 }}>
        <StatRow label="Робіт (сума)" value={worksSum} big />
        <StatRow label={`Механік (${split.mechanic}%)`} value={mechanicAmt} color={COLORS.accent2} />
        <StatRow label={`Партнер А (${split.partnerA}%)`} value={partnerAAmt} color={COLORS.accent2} />
        <StatRow label={`Партнер Б (${split.partnerB}%)`} value={partnerBAmt} color={COLORS.accent2} />
        {pctSum !== 100 && <div style={{ fontSize: 11, color: COLORS.warn }}>Сума часток: {pctSum}% (не 100%)</div>}
        <div style={{ height: 1, background: COLORS.border, margin: "4px 0" }} />
        <StatRow label="Запчастини (різниця, окремо від поділу)" value={partsSum} />
        <div style={{ height: 1, background: COLORS.border, margin: "4px 0" }} />
        <StatRow label="Кількість візитів за місяць" value={visits} isCount />
        <StatRow label="Середній чек" value={avgCheck} />
        <StatRow label="Витрати" value={expensesSum} color={COLORS.danger} />
        <StatRow label="Загальний прибуток за місяць" value={profit} big color={profit >= 0 ? COLORS.success : COLORS.danger} />
      </div>

      <SectionLabel>Дохід і витрати, 6 міс.</SectionLabel>
      <div style={{ background: COLORS.surface, border: `1px solid ${COLORS.border}`, borderRadius: 14, padding: "12px 6px", height: 210, marginTop: 8 }}>
        <ResponsiveContainer width="100%" height="100%">
          <BarChart data={chartData}>
            <CartesianGrid strokeDasharray="3 3" stroke={COLORS.border} vertical={false} />
            <XAxis dataKey="label" stroke={COLORS.textMuted} fontSize={11} tickLine={false} axisLine={{ stroke: COLORS.border }} />
            <YAxis stroke={COLORS.textMuted} fontSize={10} tickLine={false} axisLine={false} width={40} />
            <Tooltip contentStyle={{ background: COLORS.surface2, border: `1px solid ${COLORS.border}`, borderRadius: 8, fontSize: 12 }} />
            <Bar dataKey="Дохід" fill={COLORS.success} radius={[4, 4, 0, 0]} />
            <Bar dataKey="Витрати" fill={COLORS.danger} radius={[4, 4, 0, 0]} />
          </BarChart>
        </ResponsiveContainer>
      </div>

      {editingSplit && (
        <Sheet title="Розподіл прибутку" onClose={() => setEditingSplit(false)}>
          <Field label="Механік, %"><input style={inputStyle} type="number" value={split.mechanic} onChange={(e) => setSplit({ ...split, mechanic: Number(e.target.value) })} /></Field>
          <Field label="Партнер А, %"><input style={inputStyle} type="number" value={split.partnerA} onChange={(e) => setSplit({ ...split, partnerA: Number(e.target.value) })} /></Field>
          <Field label="Партнер Б, %"><input style={inputStyle} type="number" value={split.partnerB} onChange={(e) => setSplit({ ...split, partnerB: Number(e.target.value) })} /></Field>
          <PrimaryButton onClick={() => setEditingSplit(false)}>Готово</PrimaryButton>
        </Sheet>
      )}
    </div>
  );
}

function StatRow({ label, value, big, color, isCount }) {
  return (
    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", background: big ? COLORS.surface2 : "transparent", borderRadius: big ? 10 : 0, padding: big ? "10px 12px" : "2px 2px" }}>
      <span style={{ color: COLORS.textMuted, fontSize: big ? 13 : 12.5, fontWeight: big ? 600 : 400 }}>{label}</span>
      <span style={{ fontFamily: "'IBM Plex Mono', monospace", fontWeight: big ? 700 : 600, fontSize: big ? 18 : 13.5, color: color || COLORS.text }}>
        {isCount ? value : fmt(value)}
      </span>
    </div>
  );
}

